const game = new GF.Game({
  id:'harbor-courier', title:'Harbor Courier', width:960, height:540,
  palette:['#16385C','#4DC6D8','#FFF3C4','#FF7C63','#37A66A'], background:'#4DC6D8', seed:481516
});

const C={navy:'#16385C',water:'#4DC6D8',cream:'#FFF3C4',coral:'#FF7C63',green:'#37A66A',road:'#F8E7B9',ink:'#19344C',white:'#FFFDF2'};
const stops=[
  {name:'Lighthouse Café', color:'#FF7C63', parcel:{x:175,y:270}, target:{x:790,y:112}, icon:'☕'},
  {name:'Coral Market', color:'#37A66A', parcel:{x:175,y:270}, target:{x:790,y:270}, icon:'M'},
  {name:'Seabreeze Hotel', color:'#4DC6D8', parcel:{x:175,y:270}, target:{x:790,y:425}, icon:'H'}
];
const blocks=[
  {x:322,y:125,w:318,h:290,label:'Harbor Houses',color:'#FF7C63'},
  {x:680,y:148,w:112,h:82,label:'Lighthouse Lane',color:'#FFF3C4'},
  {x:682,y:310,w:120,h:78,label:'Market Awning',color:'#37A66A'},
  {x:90,y:385,w:150,h:55,label:'Boat Shed',color:'#FFF3C4'}
];
function circleRect(x,y,r,b){
  const qx=Math.max(b.x,Math.min(x,b.x+b.w));
  const qy=Math.max(b.y,Math.min(y,b.y+b.h));
  const dx=x-qx,dy=y-qy;
  return dx*dx+dy*dy<r*r;
}
function driving(input){
  return !!(input.keys.ArrowLeft||input.keys.ArrowRight||input.keys.ArrowUp||input.keys.ArrowDown||input.keys.KeyA||input.keys.KeyD||input.keys.KeyW||input.keys.KeyS||input.keys.Space||input.pointer.down);
}

const play={
  init(){ if(!this.runCount)this.runCount=0; },
  reset(){
    this.runCount=(this.runCount||0)+1;
    this.p={x:118,y:270,vx:0,vy:0,a:0};
    this.delivery=0; this.carry=false; this.timer=18; this.routeStep=0;
    this.blocked=false; this.detoured=false; this.notice='Drive to the glowing parcel crate'; this.noticeT=2.6;
    this.musicT=0; this.turnT=0; this.wasDriving=false; this.timeoutDone=false;
    if(this.runCount>1) game.event('fresh_run_started',{run:this.runCount});
  },
  objective(){
    const s=stops[this.delivery];
    if(!s)return {x:480,y:270};
    if(!this.carry)return s.parcel;
    if(this.routeStep===0)return s.target;
    if(this.routeStep===1)return {x:280,y:468};
    if(this.routeStep===2)return {x:690,y:468};
    return s.target;
  },
  update(dt){
    const s=stops[this.delivery];
    if(!s)return;
    this.timer=Math.max(0,this.timer-dt);
    this.noticeT=Math.max(0,this.noticeT-dt);
    this.musicT+=dt;
    if(this.musicT>.9){
      this.musicT=0;
      GF.Sfx.beep({freq:this.timer<7?620:360,to:this.timer<7?680:420,dur:.045,type:'triangle',vol:.045});
    }
    if(this.timer<6 && Math.floor((this.timer+dt)*2)!==Math.floor(this.timer*2)) GF.Sfx.beep({freq:780,dur:.035,type:'square',vol:.1});
    if(this.timer<=0&&!this.timeoutDone){
      this.timeoutDone=true;
      game.flash(C.coral,.4); game.shake(6,.28);
      GF.Sfx.noise({dur:.25,vol:.18,freq:220});
      game.gameOver({message:"TIME'S UP — DISPATCH MISSED"});
      return;
    }

    const active=driving(game.input);
    const p=this.p;
    let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0);
    let iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);
    if(game.input.pointer.down){ ix=game.input.pointer.x-p.x; iy=game.input.pointer.y-p.y; }
    const obj=this.objective();
    let ax=obj.x-p.x, ay=obj.y-p.y;
    let al=Math.hypot(ax,ay)||1; ax/=al; ay/=al;
    if(active){
      const il=Math.hypot(ix,iy);
      if(il>0){ ix/=il; iy/=il; ax=ax*.78+ix*.22; ay=ay*.78+iy*.22; }
      const nl=Math.hypot(ax,ay)||1; ax/=nl; ay/=nl;
      p.vx+=(ax*330-p.vx)*Math.min(1,dt*8);
      p.vy+=(ay*330-p.vy)*Math.min(1,dt*8);
    }else{
      p.vx*=Math.max(0,1-dt*7); p.vy*=Math.max(0,1-dt*7);
    }
    const oldx=p.x,oldy=p.y;
    p.x+=p.vx*dt; p.y+=p.vy*dt;
    let hit=false;
    for(const b of blocks){ if(circleRect(p.x,p.y,13,b)){hit=true;break;} }
    if(hit){
      p.x=oldx; p.y=oldy; p.vx*=-.18; p.vy*=-.18;
      if(this.carry&&this.routeStep===0){
        this.blocked=true; this.routeStep=1;
        this.notice='Building ahead! Take the sunny south street.'; this.noticeT=1.6;
        GF.Sfx.beep({freq:180,to:125,dur:.09,type:'square',vol:.13});
      }
    }
    p.x=GF.math.clamp(p.x,28,932); p.y=GF.math.clamp(p.y,100,512);
    const vl=Math.hypot(p.vx,p.vy);
    if(vl>12)p.a=Math.atan2(p.vy,p.vx);
    if(active&&!this.wasDriving&&vl>90){ game.burst(p.x,p.y,{count:3,speed:38,size:2,life:.25,colors:[C.cream],gravity:35}); }
    this.wasDriving=active;

    if(this.carry&&this.routeStep===1&&GF.math.dist(p.x,p.y,280,468)<30){this.routeStep=2;this.detoured=true;}
    if(this.carry&&this.routeStep===2&&GF.math.dist(p.x,p.y,690,468)<32){this.routeStep=3;}

    if(!this.carry&&game.time>1.55&&GF.math.dist(p.x,p.y,s.parcel.x,s.parcel.y)<38){
      this.carry=true; this.routeStep=0;
      const before=game.score; game.addScore(25);
      this.notice='Parcel aboard — follow the matching beacon!'; this.noticeT=1.8;
      game.event('parcel_collected',{stop:this.delivery+1,before:before,after:game.score});
      game.event('courier_scooter_delivery_started',{stop:this.delivery+1,target:s.name});
      game.burst(p.x,p.y,{count:13,speed:82,size:3,life:.45,colors:[s.color,C.cream],gravity:80});
      GF.Sfx.beep({freq:480,to:740,dur:.13,type:'triangle',vol:.22});
    }
    if(this.carry&&GF.math.dist(p.x,p.y,s.target.x,s.target.y)<44)this.finish(s);
  },
  finish(s){
    const before=game.score;
    game.addScore(100);
    this.carry=false;
    this.delivery++;
    game.shake(4,.16); game.flash(s.color,.35); game.hitStop(.08);
    game.burst(s.target.x,s.target.y,{count:30,speed:155,size:4,life:.75,colors:[s.color,C.cream,C.green,C.coral],gravity:150});
    GF.Sfx.noise({dur:.09,vol:.15,freq:980});
    GF.Sfx.melody([[660,.07],[880,.08],[1100,.14]],{type:'triangle',vol:.18});
    game.event('delivery_completed',{stop:this.delivery,name:s.name,before:before,after:game.score});
    if(this.blocked&&this.detoured)game.event('route_detour_completed',{stop:this.delivery,route:'south_street'});
    if(this.delivery>=3){
      game.event('third_delivery_completed',{deliveries:3,timerRemaining:Math.ceil(this.timer)});
      game.win({message:'ALL THREE DELIVERIES COMPLETE!'});
      return;
    }
    this.timer=Math.min(18,this.timer+1.5);
    this.notice='Delivered! Next parcel is waiting at Dispatch.'; this.noticeT=2;
  },
  draw(ctx){
    const W=960,H=540;
    const water=ctx.createLinearGradient(0,0,0,H);
    water.addColorStop(0,'#77DCE6'); water.addColorStop(1,'#32ACC3');
    ctx.fillStyle=water; ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.28; ctx.strokeStyle=C.cream; ctx.lineWidth=2;
    for(let y=112;y<H;y+=30){
      ctx.beginPath();
      for(let x=0;x<W;x+=50)ctx.quadraticCurveTo(x+25,y+4*Math.sin((x+y+game.time*16)/48),x+50,y);
      ctx.stroke();
    }
    ctx.globalAlpha=1;
    ctx.fillStyle=C.road; ctx.fillRect(48,92,855,420);
    ctx.fillStyle='#FFF9DF'; ctx.fillRect(60,104,831,396);
    ctx.strokeStyle='#D8B979'; ctx.lineWidth=3; ctx.setLineDash([12,11]);
    ctx.beginPath();ctx.moveTo(282,112);ctx.lineTo(282,488);ctx.moveTo(74,468);ctx.lineTo(875,468);ctx.stroke();ctx.setLineDash([]);
    for(const b of blocks){
      GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,13,'rgba(22,56,92,.22)');
      GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.color);
      ctx.fillStyle='rgba(255,255,255,.35)';ctx.fillRect(b.x+13,b.y+13,b.w-26,9);
      GF.Draw.text(ctx,b.label,b.x+b.w/2,b.y+b.h/2,{size:13,color:C.ink,weight:'800'});
    }
    for(let i=0;i<stops.length;i++){
      const s=stops[i],on=i===this.delivery;
      ctx.globalAlpha=on?1:.38; ctx.strokeStyle=s.color;ctx.lineWidth=on?5:3;
      ctx.beginPath();ctx.arc(s.target.x,s.target.y,on?32:23,0,GF.math.TAU);ctx.stroke();
      ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.target.x,s.target.y,13,0,GF.math.TAU);ctx.fill();
      GF.Draw.text(ctx,s.icon,s.target.x,s.target.y+1,{size:13,color:'#fff'});
      if(on)GF.Draw.text(ctx,s.name,s.target.x,s.target.y-43,{size:14,color:C.ink,weight:'800'});
      ctx.globalAlpha=1;
    }
    const s=stops[this.delivery];
    if(s&&!this.carry){
      const q=s.parcel,sc=1+Math.sin(game.time*6)*.1;
      ctx.save();ctx.translate(q.x,q.y);ctx.scale(sc,sc);GF.Draw.roundRect(ctx,-16,-13,32,26,4,s.color);ctx.fillStyle=C.cream;ctx.fillRect(-11,-3,22,4);ctx.restore();
      GF.Draw.text(ctx,'PARCEL',q.x,q.y-27,{size:11,color:C.ink});
    }
    if(s){
      const o=this.objective(),p=this.p;let dx=o.x-p.x,dy=o.y-p.y,dl=Math.hypot(dx,dy)||1;dx/=dl;dy/=dl;
      const ex=480+dx*432,ey=305+dy*190;
      ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(ex,ey,11+Math.sin(game.time*5)*2,0,GF.math.TAU);ctx.fill();
      ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(ex+dx*14,ey+dy*14);ctx.lineTo(ex-dy*8,ey+dx*8);ctx.lineTo(ex+dy*8,ey-dx*8);ctx.fill();
    }
    const p=this.p;
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);
    ctx.fillStyle='rgba(22,56,92,.2)';ctx.beginPath();ctx.ellipse(-2,8,22,10,0,0,GF.math.TAU);ctx.fill();
    ctx.strokeStyle=C.ink;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-14,0);ctx.lineTo(14,0);ctx.stroke();
    ctx.fillStyle=C.navy;ctx.beginPath();ctx.arc(-13,0,7,0,GF.math.TAU);ctx.arc(14,0,7,0,GF.math.TAU);ctx.fill();
    GF.Draw.roundRect(ctx,-8,-10,22,18,7,C.water);ctx.fillStyle=C.cream;ctx.fillRect(7,-6,10,4);
    if(this.carry)GF.Draw.roundRect(ctx,-17,-14,13,12,2,s.color);
    ctx.restore();

    GF.Draw.roundRect(ctx,16,10,178,45,10,'rgba(22,56,92,.94)');
    GF.Draw.text(ctx,'TIDE-CLOCK',29,25,{size:11,color:C.cream,align:'left'});
    GF.Draw.text(ctx,Math.ceil(this.timer)+'s',180,37,{size:24,color:this.timer<6?C.coral:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,210,10,202,45,10,'rgba(22,56,92,.94)');
    GF.Draw.text(ctx,this.carry?'DELIVER TO':'PICK UP FOR',223,25,{size:10,color:C.cream,align:'left'});
    GF.Draw.text(ctx,s?s.name:'Complete',{size:15,color:s?s.color:'#fff',align:'left'},0,0);
    GF.Draw.text(ctx,s?s.name:'Complete',223,40,{size:15,color:s?s.color:'#fff',align:'left'});
    GF.Draw.roundRect(ctx,550,10,174,45,10,'rgba(22,56,92,.94)');
    GF.Draw.text(ctx,'DELIVERIES',563,25,{size:10,color:C.cream,align:'left'});
    GF.Draw.text(ctx,this.delivery+' / 3',710,37,{size:21,color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,432,10,103,45,10,'rgba(22,56,92,.94)');
    GF.Draw.text(ctx,'SCORE',483,23,{size:10,color:C.cream});
    if(this.noticeT>0)GF.Draw.text(ctx,this.notice,480,520,{size:16,color:C.ink,weight:'800'});
    GF.Draw.vignette(ctx,W,H,.14);
  }
};

game.add('play',play);
game.titleScreen({subtitle:'Arrow Keys / WASD drive • Pick up parcels • Deliver before the tide-clock'});
